    rng,
    state: 'title',
    time: 0,
    player: freshPlayer(),
    bullets: [],
    enemyBullets: [],
    enemies: [],
    powerups: [],
    particles: [],
    floaters: [],
    score: 0,
    wave: 0,
    combo: 0,
    comboTimer: 0,
    kills: 0,
    spawnQueue: [],
    spawnTimer: 0,
    breather: 0,
    endless: false,
    shake: 0,
    won: false,
    shotsFired: 0,
    shotsHit: 0,
  };
}

