function addFloater(world, x, y, text, color) {
  world.floaters.push({ x, y, text, color, life: 1.0 });
}

function hurtPlayer(world, audio, dmg) {
  const p = world.player;
  if (p.invuln > 0 || p.shield > 0 || world.state !== 'playing') return;
  p.hp -= dmg;
